// This code implements a minimal homography computation from 4 point correspondences in C#.
// It depends on MathNet.Numerics (https://numerics.mathdotnet.com/) for linear algebra.
// which can be installed via NuGet (https://github.com/GlitchEnzo/NuGetForUnity)
// Authorship disclaimer: This code was partially generated by "GPT5 - Extended thinking"
using System;
using MathNet.Numerics.LinearAlgebra;

namespace Geometry
{
    /// <summary>
    /// Computes a 3x3 homography (projective transform) H from 4 point correspondences.
    ///
    /// What this means:
    ///   We want a matrix H such that a 2D point (x, y) in the "source" plane maps to (u, v)
    ///   in the "destination" plane via homogeneous coordinates:
    ///
    ///        [u v 1]^T  ~  H * [x y 1]^T
    ///
    ///   The "~" means "equal up to a nonzero scale". Homographies are defined up to scale.
    ///
    /// Why 4 points:
    ///   Each point pair gives two independent equations (one for u, one for v).
    ///   H has 8 degrees of freedom (9 entries but arbitrary overall scale),
    ///   so 4 pairs (8 equations) are enough to solve for H. This is the same setup
    ///   used by OpenCV's getPerspectiveTransform which also takes 4 pairs. 
    ///
    /// Assumptions to keep this minimal:
    ///   - Exactly 4 pairs are provided.
    ///   - Inputs are "well-posed" (no degeneracy such as all points being collinear).
    ///   - No noise handling, normalization, or RANSAC; incorrect inputs simply yield
    ///     incorrect outputs. For noisy data or >4 points, use a full DLT+SVD approach.
    ///
    /// Output:
    ///   A 3x3 H with h33 set to 1 (we fix the unknown global scale this way).
    /// </summary>
    public static class Homography
    {
        /// <summary>
        /// Build and solve a simple linear system specialized to 4 pairs.
        ///
        /// Unknown parameterization:
        ///   We write H as
        ///        [ h11 h12 h13 ]
        ///    H = [ h21 h22 h23 ]
        ///        [ h31 h32 h33 ]
        ///
        ///   Because H is up to scale, we can fix h33 = 1 without loss of generality.
        ///   That leaves 8 unknowns we pack into a vector:
        ///        h = [ h11 h12 h13 h21 h22 h23 h31 h32 ]^T
        ///
        /// From the mapping equation [U V W]^T  ~  H * [x y 1]^T, and u = U/W, v = V/W, we have:
        ///        u = (h11*x + h12*y + h13) / (h31*x + h32*y + 1)
        ///        v = (h21*x + h22*y + h23) / (h31*x + h32*y + 1)
        ///
        /// Multiply both sides by the denominator ...
        ///        (h11*x + h12*y + h13) - u*(h31*x + h32*y + 1) = 0
        ///        (h21*x + h22*y + h23) - v*(h31*x + h32*y + 1) = 0
        /// 
        /// ... expand and bring over u and v, so we only have terms with unknowns on the left:
        ///         h11*x + h12*y + h13 - h31*u*x - h32*u*y = u
        ///         h21*x + h22*y + h23 - h31*v*x - h32*v*y = v
        ///
        /// Rearranged into A*h = b (see code below), two rows per correspondence.
        ///
        /// Args:
        ///   src: four source points (x, y) in any consistent order
        ///   dst: the four destination points (u, v) corresponding to   src
        ///
        /// Returns:
        ///   3x3 double[,] H with h33 = 1.
        /// </summary>
        public static double[,] From4Points(
            (double x, double y)[] src,
            (double u, double v)[] dst)
        {
            if (src == null || dst == null || src.Length != 4 || dst.Length != 4)
                throw new ArgumentException("Provide exactly 4 source and 4 destination points.");

            // Construct an 8x8 matrix A and an 8x1 vector b for the linear system A*h = b.
            // Unknowns are ordered as:
            //   h = [h11 h12 h13 h21 h22 h23 h31 h32]^T
            // with h33 fixed to 1 to remove the arbitrary projective scale.
            var A = Matrix<double>.Build.Dense(8, 8);
            var b = Vector<double>.Build.Dense(8);

            // Each correspondence with index i contributes two rows:
            //   row 2i   encodes the "u" equation
            //   row 2i+1 encodes the "v" equation
            for (int i = 0; i < 4; i++)
            {
                double x = src[i].x, y = src[i].y;
                double u = dst[i].u, v = dst[i].v;

                int row = 2 * i;

                // ---- "u" equation:
                // h11*x + h12*y + h13 - h31*u*x - h32*u*y = u
                //
                // Set coefficients for 
                // [h11   h12   h13   h21   h22   h23   h31   h32]:
                //    x     y     1     0     0     0  -u*x  -u*y  |  b = u
                A[row, 0] = x;          // h11
                A[row, 1] = y;          // h12
                A[row, 2] = 1.0;        // h13
                A[row, 3] = 0.0;        // h21
                A[row, 4] = 0.0;        // h22
                A[row, 5] = 0.0;        // h23
                A[row, 6] = -u * x;     // h31
                A[row, 7] = -u * y;     // h32
                b[row] = u;             // b (right-hand side)

                // ---- "v" equation:
                // h21*x + h22*y + h23 - h31*v*x - h32*v*y = v
                //
                // Coefficients:
                // [h11   h12   h13   h21   h22   h23   h31   h32]:
                //   0     0     0     x     y     1   -v*x   -v*y  |  b = v
                A[row + 1, 0] = 0.0;    // h11
                A[row + 1, 1] = 0.0;    // h12
                A[row + 1, 2] = 0.0;    // h13
                A[row + 1, 3] = x;      // h21
                A[row + 1, 4] = y;      // h22
                A[row + 1, 5] = 1.0;    // h23
                A[row + 1, 6] = -v * x; // h31
                A[row + 1, 7] = -v * y; // h32
                b[row + 1] = v;         // b (right-hand side)
            }

            // Solve the 8x8 linear system for the 8 unknowns.
            // MathNet picks a reasonable direct solver under the hood (e.g., LU).
            var h = A.Solve(b);

            // Reassemble the 3x3 matrix H. We fixed h33 = 1 by design.
            var H = new double[3, 3];
            H[0, 0] = h[0]; H[0, 1] = h[1]; H[0, 2] = h[2];
            H[1, 0] = h[3]; H[1, 1] = h[4]; H[1, 2] = h[5];
            H[2, 0] = h[6]; H[2, 1] = h[7]; H[2, 2] = 1.0;

            // Done: H now maps [x y 1]^T to W * [u v]^T.
            // If you need to apply H to points elsewhere, use:
            //    W   =  H[2,0]*x + H[2,1]*y + H[2,2];
            //    u   = (H[0,0]*x + H[0,1]*y + H[0,2]) / W;
            //    v   = (H[1,0]*x + H[1,1]*y + H[1,2]) / W;
            return H;
        }
    }
}
